Loops let you execute code repeatedly. Instead of writing:

```
printf("Hello\n");
printf("Hello\n");
printf("Hello\n");
```

You can write a loop that repeats 3 times. BPL uses the `loop` keyword for all types of loops.

languages.Python:
while cond:
    pass
for i in range(10):
    pass

sections.code:
import [printf] from "std/c.bpl";

frame main() ret int {
    # Basic while loop - runs while condition is true
    local count: int = 1;

    printf("Counting to 5:\n");
    loop (count <= 5) {
        printf("%d ", count);
        count = count + 1;  # Don't forget to update!
    }
    printf("\n");

    # Countdown example
    local rocket: int = 3;
    printf("\nLaunch sequence:\n");
    loop (rocket > 0) {
        printf("%d...\n", rocket);
        rocket = rocket - 1;
    }
    printf("Liftoff!\n");

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Classic for loop: (init; condition; update)
    printf("For loop 0-4:\n");
    loop (local i: int = 0; i < 5; i = i + 1) {
        printf("%d ", i);
    }
    printf("\n");

    # Count by 2s
    printf("\nEven numbers 0-10:\n");
    loop (local j: int = 0; j <= 10; j = j + 2) {
        printf("%d ", j);
    }
    printf("\n");

    # Countdown with for
    printf("\nCountdown:\n");
    loop (local k: int = 5; k >= 1; k = k - 1) {
        printf("%d ", k);
    }
    printf("\n");

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Find first number divisible by 7 after 50
    printf("Finding first number > 50 divisible by 7:\n");

    loop (local i: int = 51; i < 100; i = i + 1) {
        if (i % 7 == 0) {
            printf("Found: %d\n", i);
            break;  # Exit the loop immediately
        }
    }

    # Search example
    local target: int = 7;
    local found: bool = false;

    loop (local j: int = 1; j <= 10; j = j + 1) {
        printf("Checking %d... ", j);
        if (j == target) {
            printf("Found it!\n");
            found = true;
            break;
        }
        printf("nope\n");
    }

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Print only odd numbers
    printf("Odd numbers 1-10:\n");
    loop (local i: int = 1; i <= 10; i = i + 1) {
        if (i % 2 == 0) {
            continue;  # Skip even numbers
        }
        printf("%d ", i);
    }
    printf("\n");

    # Skip number 5
    printf("\n1-10 (skipping 5):\n");
    loop (local j: int = 1; j <= 10; j = j + 1) {
        if (j == 5) {
            continue;
        }
        printf("%d ", j);
    }
    printf("\n");

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Infinite loop - use with caution!
    # loop { } runs forever unless you break out

    local count: int = 0;

    printf("Infinite loop with break:\n");
    loop {
        count = count + 1;
        printf("Iteration %d\n", count);

        if (count >= 3) {
            printf("Breaking out!\n");
            break;
        }
    }

    # Common pattern: input validation loop
    # (simulated here)
    local attempts: int = 0;
    local valid: bool = false;

    loop {
        attempts = attempts + 1;
        printf("Attempt %d: ", attempts);

        # Simulate: 3rd attempt is valid
        if (attempts == 3) {
            valid = true;
            printf("Valid input!\n");
            break;
        }
        printf("Invalid, try again\n");
    }

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Multiplication table (3x3)
    printf("Multiplication Table:\n");
    printf("  ");
    loop (local h: int = 1; h <= 3; h = h + 1) {
        printf("%4d", h);
    }
    printf("\n");
    printf("  +------------\n");

    loop (local i: int = 1; i <= 3; i = i + 1) {
        printf("%d |", i);
        loop (local j: int = 1; j <= 3; j = j + 1) {
            printf("%4d", i * j);
        }
        printf("\n");
    }

    # Pattern: right triangle
    printf("\nTriangle pattern:\n");
    loop (local row: int = 1; row <= 5; row = row + 1) {
        loop (local col: int = 0; col < row; col = col + 1) {
            printf("* ");
        }
        printf("\n");
    }

    return 0;
}

sections.content:
⚠️ **Infinite Loop** - Forgetting to update the loop variable
```bpl
local i: int = 0;
loop (i < 10) {
    printf("%d", i);
    # Oops! Forgot i = i + 1;
}
```

⚠️ **Off-by-One Errors** - Using < vs <= incorrectly
```bpl
# This prints 0-9 (10 numbers)
loop (local i: int = 0; i < 10; i = i + 1) { }

# This prints 0-10 (11 numbers)
loop (local i: int = 0; i <= 10; i = i + 1) { }
```

⚠️ **Wrong Update Direction** - Incrementing when you should decrement
```bpl
# This never stops! 10 is always > 0
loop (local i: int = 10; i > 0; i = i + 1) { }
```

sections.solution:
import [printf] from "std/c.bpl";

frame main() ret int {
    local sum: int = 0;

    loop (local i: int = 1; i <= 10; i = i + 1) {
        sum = sum + i;
        printf("Added %d, sum is now %d\n", i, sum);
    }

    printf("Final sum: %d\n", sum);

    return 0;
}
